import numpy as np
from scipy.linalg import sqrtm

def compute_fid(real_embeds, synth_embeds):
    # FID assumes Gaussianity and compares first two moments
    mu_r, sigma_r = np.mean(real_embeds, axis=0), np.cov(real_embeds, rowvar=False)
    mu_s, sigma_s = np.mean(synth_embeds, axis=0), np.cov(synth_embeds, rowvar=False)

    diff = mu_r - mu_s
    covmean, _ = sqrtm(sigma_r.dot(sigma_s), disp=False)
    if np.iscomplexobj(covmean):
        covmean = covmean.real

    return diff.dot(diff) + np.trace(sigma_r + sigma_s - 2 * covmean)

def compute_mind_1d(real_proj, synth_proj):
    # Sliced Wasserstein distance in 1D is efficiently computed via sorting
    return np.mean((np.sort(real_proj) - np.sort(synth_proj)) ** 2)
